import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"《乐事薯片》AI 创意视频分析","description":"","frontmatter":{},"headers":[],"relativePath":"cases/case-05-lays-ai-video.md","filePath":"cases/case-05-lays-ai-video.md","lastUpdated":1786503105000}'),l={name:"cases/case-05-lays-ai-video.md"};function i(o,t,h,s,n,c){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="《乐事薯片》ai-创意视频分析" tabindex="-1">《乐事薯片》AI 创意视频分析 <a class="header-anchor" href="#《乐事薯片》ai-创意视频分析" aria-label="Permalink to &quot;《乐事薯片》AI 创意视频分析&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">先说清楚这篇的性质</p><p>这是对<strong>第三方公开发布的 AI 创作作品</strong>的逆向拆解，不是项目复盘。</p><ul><li>原片由抖音创作者「宿舍食光」发布，属于个人 AI 创作，<strong>不是乐事官方广告</strong>，与百事公司及其关联品牌无关。</li><li>文中的时间轴、镜头切点、声音设计判断均为<strong>观看推测</strong>，不是原作者提供的制作记录。</li><li>涉及的品牌名称与包装仅用于分析对象的指称，著作权与商标权归各自权利人所有。</li></ul></div><div class="tip custom-block"><p class="custom-block-title">它和前四篇不是一类内容</p><p>案例 01–04 是「从 brief 到成片」的正向复盘，有 Prompt、有链路、有工期。</p><p>这一篇是<strong>逆向的</strong>：只有成片，没有制作过程，所有结论都是从画面倒推出来的。</p><p>两种读法的价值不同——正向看的是&quot;怎么做&quot;，逆向看的是**&quot;做出来之后长什么样，哪里露馅&quot;**。逆向拆解是能大量做的，公开的 AI 广告作品到处都是，而这类练习对培养判断力的效率很高。</p></div><h2 id="一、项目概览" tabindex="-1">一、项目概览 <a class="header-anchor" href="#一、项目概览" aria-label="Permalink to &quot;一、项目概览&quot;">​</a></h2><ul><li>原视频：<a href="https://www.douyin.com/video/7608915231386399817" target="_blank" rel="noreferrer">宿舍食光《今天的 AI 短片——薯片》</a></li><li>成片时长：约 67.8 秒</li><li>广告主体：约 0–64.8 秒</li><li>账号尾卡：约 64.8–67.8 秒</li><li>画面形式：竖屏文件内嵌横向 16:9 主画面</li><li>内容类型：AI 生成产品感官广告</li><li>核心卖点：金黄、酥脆、美味、分享</li><li>配乐：<code>sunny side up - Chill Around</code></li></ul><p>这支短片没有设置传统人物故事，而是通过包装悬浮、薯片飞散、微距纹理和多人分享等画面，持续强化产品的感官吸引力。整体叙事可概括为：</p><blockquote><p>品牌亮相 → 证明酥脆 → 制造食欲 → 放大质感 → 重回包装 → 分享场景 → 产品矩阵</p></blockquote><h2 id="二、创意概念" tabindex="-1">二、创意概念 <a class="header-anchor" href="#二、创意概念" aria-label="Permalink to &quot;二、创意概念&quot;">​</a></h2><p>影片将一袋普通薯片塑造成金色光场中的“主角”。包装和薯片不再遵循日常物理状态，而是通过悬浮、旋转、喷涌、碎裂和慢速飘落等视觉动作，建立夸张的食欲奇观。</p><p>创意表达主要依靠三组视觉符号：</p><ul><li><strong>金色光线</strong>：对应烘烤感、香味和愉悦感。</li><li><strong>薯片碎屑与翻转</strong>：对应酥脆和入口时的声音联想。</li><li><strong>包装反复出现</strong>：在连续的食物特写中维持品牌记忆。</li></ul><h2 id="三、分镜与脚本拆解" tabindex="-1">三、分镜与脚本拆解 <a class="header-anchor" href="#三、分镜与脚本拆解" aria-label="Permalink to &quot;三、分镜与脚本拆解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>画面与镜头</th><th>字幕或文案</th><th>声音设计</th><th>镜头作用</th></tr></thead><tbody><tr><td>0:00–0:02</td><td>乐事黄袋正面立于中央，薯片环绕飞落，暖金逆光照亮包装</td><td>无</td><td>音乐起势，配合轻微落片声</td><td>开门见品牌，建立产品主视觉</td></tr><tr><td>0:02–0:05</td><td>包装悬浮并轻微旋转，背景形成金色光束</td><td>无</td><td>上扬音效或轻微呼啸声</td><td>将普通包装塑造成英雄产品</td></tr><tr><td>0:05–0:09</td><td>两块薯片超微距分开，碎屑向四周飞散</td><td>黄金酥脆，每一口都充满滋味 / 舌尖上的脆响，越吃越上头</td><td>脆裂声、碎屑声突出于音乐</td><td>第一轮感官证明：脆</td></tr><tr><td>0:09–0:14</td><td>包装倾斜，薯片从袋口喷涌，金色光轨环绕</td><td>无</td><td>喷涌声、转场呼啸声</td><td>制造丰富、停不下来的食欲感</td></tr><tr><td>0:14–0:18.7</td><td>单片薯片悬浮特写，表面油光、气泡和褶皱清晰可见</td><td>乐事，让每一口都值得回味</td><td>音乐稍放缓，保留清脆点音</td><td>总结产品价值，结束第一段高潮</td></tr><tr><td>0:18.7–0:25.6</td><td>黑色背景中薯片缓慢掉落、翻转并堆积</td><td>无</td><td>低频减弱，突出空气感与落片声</td><td>利用明暗反差展示形态</td></tr><tr><td>0:25.6–0:32</td><td>镜头极近距离扫过薯片表面的气泡、颗粒和褶皱</td><td>美味</td><td>细碎摩擦声、轻微脆响</td><td>第二轮感官证明：质地与香味</td></tr><tr><td>0:32–0:42</td><td>大量薯片堆叠、翻动，镜头持续缓慢推进</td><td>无</td><td>音乐保持稳定，画面内部运动维持节奏</td><td>延长食欲刺激，但信息开始重复</td></tr><tr><td>0:42–0:55.3</td><td>暗场后重新出现产品包装，薯片持续在前后景飞舞，包装逐渐被托起</td><td>无</td><td>音乐重新增强，飞片声逐步叠加</td><td>回到品牌，形成第二次产品高潮</td></tr><tr><td>0:55.3–0:59.7</td><td>俯拍多人伸手，从打开的包装中取出薯片</td><td>无</td><td>加入包装摩擦、拿取和轻微人群氛围</td><td>第一次落到真实消费与分享场景</td></tr><tr><td>0:59.7–1:04.8</td><td>蓝、黄、橙多袋产品共同陈列，镜头贴近包装推进</td><td>乐事薯片</td><td>终拍加强，音乐开始收束</td><td>从单品扩展到系列产品，完成品牌收口</td></tr><tr><td>1:04.8–1:07.8</td><td>“Bye Bye”及作者账号搜索尾卡</td><td>Bye Bye / 宿舍食光</td><td>广告音乐停止或进入静音</td><td>创作者导流，不属于广告主体</td></tr></tbody></table><p>主要硬切点约为 5.0、9.4、18.7、25.6、55.3、59.7 和 64.8 秒。中段较多使用连续形变、暗场和物体运动衔接，因此整体更接近“一镜式视觉流”，而不是传统的高频快剪。</p><h2 id="四、脚本结构" tabindex="-1">四、脚本结构 <a class="header-anchor" href="#四、脚本结构" aria-label="Permalink to &quot;四、脚本结构&quot;">​</a></h2><p>影片几乎不依赖人物对白，脚本主要由画面行动和屏幕文案构成。</p><h3 id="画面脚本" tabindex="-1">画面脚本 <a class="header-anchor" href="#画面脚本" aria-label="Permalink to &quot;画面脚本&quot;">​</a></h3><ol><li>乐事包装在金色光场中登场。</li><li>薯片破裂和碎屑飞散，证明产品酥脆。</li><li>包装倾斜，薯片大量喷涌，放大满足感。</li><li>单片薯片微距展示，强调质地和回味。</li><li>薯片在黑色背景中翻转、掉落和堆积。</li><li>镜头继续放大纹理，强化“美味”联想。</li><li>包装再次回到画面中心，完成品牌强化。</li><li>多人共同取食，补充真实消费场景。</li><li>多口味包装陈列，品牌统一收尾。</li></ol><h3 id="文案脚本" tabindex="-1">文案脚本 <a class="header-anchor" href="#文案脚本" aria-label="Permalink to &quot;文案脚本&quot;">​</a></h3><blockquote><p>黄金酥脆，每一口都充满滋味。</p><p>舌尖上的脆响，越吃越上头。</p><p>乐事，让每一口都值得回味。</p><p>美味。</p><p>乐事薯片。</p></blockquote><p>文案的作用不是推动情节，而是为食物特写提供语义锚点。表达集中在“脆”和“好吃”，与画面形成直接对应。</p><h2 id="五、视频节奏分析" tabindex="-1">五、视频节奏分析 <a class="header-anchor" href="#五、视频节奏分析" aria-label="Permalink to &quot;五、视频节奏分析&quot;">​</a></h2><h3 id="_1-0–18-7-秒-快速建立卖点" tabindex="-1">1. 0–18.7 秒：快速建立卖点 <a class="header-anchor" href="#_1-0–18-7-秒-快速建立卖点" aria-label="Permalink to &quot;1. 0–18.7 秒：快速建立卖点&quot;">​</a></h3><p>前段平均每 4–5 秒切换一次视觉命题，依次完成包装亮相、薯片碎裂、产品喷涌和单片特写。品牌、卖点和感官证据都较完整，是全片信息效率最高的部分。</p><h3 id="_2-18-7–42-秒-食欲沉浸段" tabindex="-1">2. 18.7–42 秒：食欲沉浸段 <a class="header-anchor" href="#_2-18-7–42-秒-食欲沉浸段" aria-label="Permalink to &quot;2. 18.7–42 秒：食欲沉浸段&quot;">​</a></h3><p>剪辑速度明显放慢，主要依赖薯片翻转、掉落、堆积以及镜头推进维持观看。画面质感统一，但约 23 秒都在重复“薯片酥脆、金黄、好吃”，容易产生视觉疲劳，也是最可能出现观看流失的部分。</p><h3 id="_3-42–55-3-秒-品牌二次强化" tabindex="-1">3. 42–55.3 秒：品牌二次强化 <a class="header-anchor" href="#_3-42–55-3-秒-品牌二次强化" aria-label="Permalink to &quot;3. 42–55.3 秒：品牌二次强化&quot;">​</a></h3><p>包装重新成为画面中心，薯片在前后景飞舞，视觉能量再次上升。该段与片头形成首尾呼应，帮助观众在大量食物特写之后重新记住品牌。</p><h3 id="_4-55-3–64-8-秒-消费场景与品牌收口" tabindex="-1">4. 55.3–64.8 秒：消费场景与品牌收口 <a class="header-anchor" href="#_4-55-3–64-8-秒-消费场景与品牌收口" aria-label="Permalink to &quot;4. 55.3–64.8 秒：消费场景与品牌收口&quot;">​</a></h3><p>影片在最后 10 秒才出现人物和分享行为，随后展示多口味产品矩阵。叙事从纯感官刺激回到“大家一起吃”的实际使用场景，并以品牌名完成收尾。</p><h3 id="_5-音乐与声音节奏" tabindex="-1">5. 音乐与声音节奏 <a class="header-anchor" href="#_5-音乐与声音节奏" aria-label="Permalink to &quot;5. 音乐与声音节奏&quot;">​</a></h3><p>配乐气质轻松、明亮，鼓点并不强烈。影片主要依靠画面内部运动维持节奏，包括薯片飞行、包装旋转、镜头推进和碎屑爆开。广告音频在约 64.7 秒后进入静音，与广告主体结束时间一致。</p><h2 id="六、导演执行重点" tabindex="-1">六、导演执行重点 <a class="header-anchor" href="#六、导演执行重点" aria-label="Permalink to &quot;六、导演执行重点&quot;">​</a></h2><h3 id="_1-锁定包装和品牌资产" tabindex="-1">1. 锁定包装和品牌资产 <a class="header-anchor" href="#_1-锁定包装和品牌资产" aria-label="Permalink to &quot;1. 锁定包装和品牌资产&quot;">​</a></h3><p>产品包装应使用真实产品图、3D 模型或后期合成，不能完全交给生成模型自由发挥。需要逐镜检查 Logo、包装文字、袋口结构、口味名称和包装颜色，避免在运动中漂移或变形。</p><h3 id="_2-统一光线和色彩逻辑" tabindex="-1">2. 统一光线和色彩逻辑 <a class="header-anchor" href="#_2-统一光线和色彩逻辑" aria-label="Permalink to &quot;2. 统一光线和色彩逻辑&quot;">​</a></h3><p>全片以金黄、琥珀色和暖白逆光为主。产品正面必须始终有清晰的主光，背景光效不能压住 Logo。黑背景段可以作为视觉换气，但薯片本身仍需保留金色轮廓光。</p><h3 id="_3-提前规定物体运动方向" tabindex="-1">3. 提前规定物体运动方向 <a class="header-anchor" href="#_3-提前规定物体运动方向" aria-label="Permalink to &quot;3. 提前规定物体运动方向&quot;">​</a></h3><p>每个镜头都应明确薯片的进入方向、离开方向、旋转速度和景深层次。下一镜延续相同运动趋势，才能形成自然的运动匹配转场，避免 AI 片段之间只是简单拼接。</p><h3 id="_4-把微距质感作为制作核心" tabindex="-1">4. 把微距质感作为制作核心 <a class="header-anchor" href="#_4-把微距质感作为制作核心" aria-label="Permalink to &quot;4. 把微距质感作为制作核心&quot;">​</a></h3><p>需要重点控制薯片边缘厚度、表面气泡、调味颗粒、轻微油光和断裂碎屑。油光过多会像塑料，厚度过大会像锅巴，纹理过度重复则容易暴露生成痕迹。</p><h3 id="_5-用声音完成-酥脆-体验" tabindex="-1">5. 用声音完成“酥脆”体验 <a class="header-anchor" href="#_5-用声音完成-酥脆-体验" aria-label="Permalink to &quot;5. 用声音完成“酥脆”体验&quot;">​</a></h3><p>建议单独设计薯片断裂声、碎屑落下声、包装摩擦声、飞行呼啸声和拿取声。脆裂声应比背景音乐更靠前，尤其在 5 秒和 15 秒附近需要形成明显声音撞点。</p><h3 id="_6-控制强弱变化" tabindex="-1">6. 控制强弱变化 <a class="header-anchor" href="#_6-控制强弱变化" aria-label="Permalink to &quot;6. 控制强弱变化&quot;">​</a></h3><p>全片应至少形成三次层次：包装亮相的小高潮、薯片喷涌的第一高潮、分享与多产品尾版的最终高潮。中间增加短暂安静、暗场或低运动镜头，可以避免持续金黄飞舞造成疲劳。</p><h3 id="_7-提前建立人物关系" tabindex="-1">7. 提前建立人物关系 <a class="header-anchor" href="#_7-提前建立人物关系" aria-label="Permalink to &quot;7. 提前建立人物关系&quot;">​</a></h3><p>原片直到 55 秒才出现“谁在吃”。如果用于正式投放，可以在前 10 秒加入手撕包装或拿起薯片的动作，结尾再回到多人分享，让动作和情绪形成闭环。</p><h3 id="_8-按平台画幅重新构图" tabindex="-1">8. 按平台画幅重新构图 <a class="header-anchor" href="#_8-按平台画幅重新构图" aria-label="Permalink to &quot;8. 按平台画幅重新构图&quot;">​</a></h3><p>当前文件虽然采用竖屏画布，但核心画面是横向 16:9 内容，上下存在大面积黑区。正式发布应直接生成或重构为 1080×1920 全屏竖构图，并将包装、薯片和字幕放在平台 UI 安全区内。</p><h3 id="_9-字幕必须后期制作" tabindex="-1">9. 字幕必须后期制作 <a class="header-anchor" href="#_9-字幕必须后期制作" aria-label="Permalink to &quot;9. 字幕必须后期制作&quot;">​</a></h3><p>中文文案、品牌名和口味信息应在剪辑或合成阶段统一添加，不能由生成模型直接生成。字幕需保持字体、字号、字重和安全边距一致，同时确保在明亮金色背景上仍有足够对比度。</p><h2 id="七、成片优点与问题" tabindex="-1">七、成片优点与问题 <a class="header-anchor" href="#七、成片优点与问题" aria-label="Permalink to &quot;七、成片优点与问题&quot;">​</a></h2><h3 id="主要优点" tabindex="-1">主要优点 <a class="header-anchor" href="#主要优点" aria-label="Permalink to &quot;主要优点&quot;">​</a></h3><ul><li>暖金色视觉风格统一，产品氛围明确。</li><li>包装出现频率高，能够维持品牌识别。</li><li>微距、碎屑和飞片动作有效建立酥脆联想。</li><li>从单品展示到多人分享再到产品矩阵，收尾逻辑完整。</li></ul><h3 id="主要问题" tabindex="-1">主要问题 <a class="header-anchor" href="#主要问题" aria-label="Permalink to &quot;主要问题&quot;">​</a></h3><ul><li>18.7–42 秒内容重复，整体时长偏长。</li><li>人物和实际消费场景出现过晚，情感温度不足。</li><li>包装与文字存在 AI 生成变形风险，需要真实资产兜底。</li><li>横画面嵌入竖屏，平台有效显示面积利用率较低。</li><li>视觉运动持续偏满，缺少足够的安静段和声音反差。</li></ul><h2 id="八、优化方向" tabindex="-1">八、优化方向 <a class="header-anchor" href="#八、优化方向" aria-label="Permalink to &quot;八、优化方向&quot;">​</a></h2><p>如果用于短视频商业投放，建议将主体压缩到 30–35 秒：</p><table tabindex="0"><thead><tr><th>建议时长</th><th>内容</th></tr></thead><tbody><tr><td>0–4 秒</td><td>包装亮相，立即建立品牌</td></tr><tr><td>4–9 秒</td><td>薯片碎裂微距，突出酥脆</td></tr><tr><td>9–14 秒</td><td>包装喷涌，形成第一高潮</td></tr><tr><td>14–20 秒</td><td>纹理、颗粒和单片特写</td></tr><tr><td>20–26 秒</td><td>打开包装与多人分享</td></tr><tr><td>26–32 秒</td><td>多口味产品矩阵与品牌尾版</td></tr><tr><td>32–35 秒</td><td>保留品牌口号或行动提示</td></tr></tbody></table><p>压缩时应优先删除中段重复的薯片堆叠和慢速翻转镜头，保留最有辨识度的碎裂、喷涌、包装英雄镜头和分享场景。这样既能延续原片的感官奇观风格，也能提高信息密度和商业传播效率。</p><h2 id="九、总结" tabindex="-1">九、总结 <a class="header-anchor" href="#九、总结" aria-label="Permalink to &quot;九、总结&quot;">​</a></h2><p>这支作品是一条以产品视觉奇观为核心的 AI 食品广告。它没有依赖复杂故事，而是利用包装、薯片运动、微距质感和金色光效持续制造食欲。执行上最值得借鉴的是统一的视觉母题和高频品牌露出；正式商业制作时，则需要重点解决包装一致性、中段节奏重复、声音质感和竖屏构图问题。</p><p>导演层面的核心任务可以归纳为一句话：</p><blockquote><p>用真实包装锁住品牌，用微距与声音制造酥脆，用运动匹配维持流畅，最后让产品回到真实的分享场景。</p></blockquote><h2 id="接着看" tabindex="-1">接着看 <a class="header-anchor" href="#接着看" aria-label="Permalink to &quot;接着看&quot;">​</a></h2><p>这篇的几条结论，在知识库其他文章里有正向的展开：</p><table tabindex="0"><thead><tr><th>本文的观察</th><th>对应的方法</th></tr></thead><tbody><tr><td>包装不能交给生成模型自由发挥</td><td><a href="/tools/decision-tree">选型决策树 · 产品必须精确还原吗</a></td></tr><tr><td>油光过多像塑料、纹理重复暴露生成痕迹</td><td><a href="/cases/case-03-fries-social">案例 03 · 食欲感风格包</a> —— 同一个塑料感问题的 Prompt 级解法</td></tr><tr><td>声音要单独设计，脆裂声压过音乐</td><td><a href="/cases/case-03-fries-social">案例 03 · 可复用套路第 4 条</a> —— 食品类里音效比配乐重要</td></tr><tr><td>中段 23 秒重复，应压缩到 30–35 秒</td><td><a href="/cases/case-03-fries-social">案例 03</a>、<a href="/cases/case-01-beverage-tvc">案例 01</a> 的复盘都指向同一件事：铺垫和重复是最先该砍的</td></tr><tr><td>字幕必须后期加，不能生成</td><td><a href="/cases/case-04-vf-fries-crisp">案例 04 · 镜头 7 包装出镜</a></td></tr><tr><td>同为薯片、但走工艺路线会怎么拍</td><td><a href="/cases/case-04-vf-fries-crisp">案例 04 · VF 工艺薯条脆</a>、<a href="/cases/case-04-fries-crisp-formats">片型可行性分析</a></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">值得注意的一处交叉验证</p><p>本片「18.7–42 秒重复导致流失」的判断，和 <a href="/cases/case-01-beverage-tvc">案例 01</a>、<a href="/cases/case-03-fries-social">案例 03</a> 两篇「如果重做一次」得出的结论完全一致——<strong>都是节奏上的冗余，都出现在中前段</strong>。</p><p>三个不同来源指向同一个问题，说明这不是偶然失误，而是 AI 生成广告的<strong>结构性倾向</strong>：素材生成变便宜之后，人会倾向于把好看的镜头全用上，于是片子变长、信息密度下降。</p><p><strong>这是目前 AI 广告最普遍的一个通病，值得单独警惕。</strong></p></div>',68)])])}const b=a(l,[["render",i]]);export{u as __pageData,b as default};
